251	    /**
252	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
253	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
254	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
255	     * a known region (see {@link Region}), the postcode must fall within that region's range
256	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
257	     * postcode.
258	     *
259	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
260	     */
261	    private void assertPostcodeValid(Owner owner) {
262	        String postcode = owner.getPostcode();
263	        if (postcode == null) {
264	            return;
265	        }
266	        String region = Region.forCity(owner.getCity());
267	        int[] range = region == null ? null : Region.postcodeRange(region);
268	        if (range == null) {
269	            return;
270	        }
271	        int value = Integer.parseInt(postcode);
272	        if (value < range[0] || value > range[1]) {
273	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
274	        }
275	    }
276	
277	    @Override
278	    @Transactional
279	    public void saveOwner(Owner owner) throws DataAccessException {
280	        assertPostcodeValid(owner);
281	        if (owner.getTelephone() != null) {
282	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
283	        }
284	        if (owner.getEmail() != null) {
285	            owner.setEmail(normalizeEmail(owner.getEmail()));
286	        }
287	        if (owner.getAddress() != null) {
288	            owner.setAddress(normalizeAddress(owner.getAddress()));
289	        }
290	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
291	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
292	        if (owner.getCustomerCode() == null) {
293	            owner.setCustomerCode(generateCustomerCode(owner));
294	        }
295	        boolean creating = owner.isNew();
296	        if (creating) {
297	            owner.setNamesakeCount(countNamesakes(owner));
298	            assertDailyCapacity(owner);
299	            assertCityCapacity(owner);
300	        }
301	        List<Owner> household = findHouseholdMembers(owner);
302	        assignHousehold(owner, household);
303	        assertIdentityUnique(owner);
304	        ownerRepository.save(owner);
305	        populateHouseholdSize(owner);
306	        if (creating) {
307	            AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
308	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
309	                owner.getMembershipLevel());
310	        }
311	    }
312	
313	    /**
314	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
315	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
316	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
317	     * one more than the number of owners already in that city.
318	     */
319	    private String generateCustomerCode(Owner owner) {
320	        String cityPrefix = prefix3(owner.getCity());
321	        String lastNamePrefix = prefix3(owner.getLastName());
322	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
323	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
324	    }
325	
326	    private static String prefix3(String value) {
327	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
328	    }
329	
330	    /** Maximum number of owners permitted in a single city. */
331	    private static final long CITY_OWNER_LIMIT = 50L;
332	
333	    /**
334	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
335	     * more owners, so no city can grow beyond the capacity limit.
336	     *
337	     * @throws CityOwnerLimitException if the owner's city is already at capacity
338	     */
339	    private void assertCityCapacity(Owner owner) {
340	        if (owner.getCity() == null) {
341	            return;
342	        }
343	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
344	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
345	        }
346	    }
347	
348	    /**
349	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
350	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
351	     */
352	    private static LocalDate rollToBusinessDay(LocalDate date) {
353	        switch (date.getDayOfWeek()) {
354	            case SATURDAY:
355	                return date.plusDays(2);
356	            case SUNDAY:
357	                return date.plusDays(1);
358	            default:
359	                return date;
360	        }
361	    }
362	
363	    /** Maximum number of owners permitted to be registered on a single day. */
364	    private static final long DAILY_OWNER_LIMIT = 100L;
365	
366	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
367	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
368	
369	    /**
370	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
371	     * today, reusing the same daily accumulation as the per-day create limit ({@link
372	     * #assertDailyCapacity}).
373	     */
374	    @Override
375	    @Transactional(readOnly = true)
376	    public boolean isBulkSignupWarningActive() throws DataAccessException {
377	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
378	    }
379	
380	    /**
381	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
382	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
383	     * many owners can be created on any single day.
384	     *
385	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
386	     */
387	    private void assertDailyCapacity(Owner owner) {
388	        LocalDate date = owner.getRegistrationDate();
389	        if (date == null) {
390	            return;
391	        }
392	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
393	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
394	        }
395	    }
396	
397	    private long countOwnersRegisteredOn(LocalDate date) {
398	        return ownerRepository.findAll().stream()
399	                .filter(existing -> date.equals(existing.getRegistrationDate()))
400	                .count();
401	    }
402	
403	    private long countOwnersInCity(String city) {
404	        String normalized = normalizeHouseholdValue(city);
405	        return ownerRepository.findAll().stream()
406	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
407	                .count();
408	    }
409	
410	    /**
411	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
412	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
413	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
414	     * that already existed before this create.
415	     */
416	    private int countNamesakes(Owner owner) {
417	        String firstName = normalizeHouseholdValue(owner.getFirstName());
418	        String lastName = normalizeHouseholdValue(owner.getLastName());
419	        int count = 0;
420	        for (Owner existing : ownerRepository.findAll()) {
421	            if (!existing.getId().equals(owner.getId())
422	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
423	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
424	                count++;
425	            }
426	        }
427	        return count;
428	    }
429	
430	    private static String normalizeEmail(String email) {
431	        return email == null ? null : email.toLowerCase(Locale.ROOT);
432	    }
433	
434	    /** Common street-type abbreviations expanded during address normalization. */
435	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
436	        "ST", "STREET",
437	        "RD", "ROAD",
438	        "AVE", "AVENUE");
439	
440	    /**
441	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
442	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
443	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
444	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
445	     * form.
446	     */
447	    private static String normalizeAddress(String address) {
448	        if (address == null) {
449	            return null;
450	        }
451	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
452	        if (collapsed.isEmpty()) {
453	            return "";
454	        }
455	        String[] tokens = collapsed.split(" ");
456	        StringBuilder sb = new StringBuilder(collapsed.length());
457	        for (int i = 0; i < tokens.length; i++) {
458	            if (i > 0) {
459	                sb.append(' ');
460	            }
461	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
462	        }
463	        return sb.toString();
464	    }
465	
466	    private static String normalizeTelephone(String telephone) {
467	        return telephone == null ? null : E164Telephone.toE164(telephone);
468	    }
469	
470	    /**
471	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
472	     * that of another owner. This single check consolidates the former separate telephone, email and
473	     * household duplicate rules: because the normalized telephone is part of the key, two members of
474	     * the same household (same {@code householdId}) with different telephones have different keys and
475	     * are both allowed — only an exact full-key match is a duplicate.
476	     *
477	     * @throws DuplicateIdentityException if another owner already has the same identity key
478	     */
479	    private void assertIdentityUnique(Owner owner) {
480	        String identityKey = owner.getIdentityKey();
481	        for (Owner existing : ownerRepository.findAll()) {
482	            if (!existing.getId().equals(owner.getId()) && identityKey.equals(existing.getIdentityKey())) {
483	                throw new DuplicateIdentityException(identityKey);
484	            }
485	        }
486	    }
487	
488	    /**
489	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
490	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
491	     * members of the household it would join. Returns an empty list for an update to an existing
492	     * owner or when either household value is blank, so household rules only apply to genuine new
493	     * members.
494	     */
495	    private List<Owner> findHouseholdMembers(Owner owner) {
496	        if (!owner.isNew()) {
497	            return List.of();
498	        }
499	        String lastName = normalizeHouseholdValue(owner.getLastName());
500	        String address = normalizeHouseholdAddress(owner.getAddress());
501	        if (lastName.isEmpty() || address.isEmpty()) {
502	            return List.of();
503	        }
504	        List<Owner> household = new ArrayList<>();
505	        for (Owner existing : ownerRepository.findAll()) {
506	            if (!existing.getId().equals(owner.getId())
507	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
508	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
509	                household.add(existing);
510	            }
511	        }
512	        return household;
513	    }
514	
515	    /**
516	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
517	     * owner and every matching existing member that lacks one are given the same stable
518	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
519	     * is empty.
520	     */
521	    private void assignHousehold(Owner owner, List<Owner> household) {
522	        if (household.isEmpty()) {
523	            return;
524	        }
525	        String householdId = resolveHouseholdId(owner, household);
526	        owner.setHouseholdId(householdId);
527	        for (Owner existing : household) {
528	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
529	                existing.setHouseholdId(householdId);
530	                ownerRepository.save(existing);
531	            }
532	        }
533	    }
534	
535	    /**
536	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
537	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
538	     * reaching into the data store. A {@code null} owner or one without a household id is left at
539	     * size 0.
540	     */
541	    private void populateHouseholdSize(Owner owner) {
542	        if (owner == null) {
543	            return;
544	        }
545	        String householdId = owner.getHouseholdId();
546	        if (householdId == null || householdId.isBlank()) {
547	            owner.setHouseholdSize(0);
548	            return;
549	        }
550	        int count = 0;
551	        for (Owner existing : ownerRepository.findAll()) {
552	            if (householdId.equals(existing.getHouseholdId())) {
553	                count++;
554	            }
555	        }
556	        owner.setHouseholdSize(count);
557	    }
558	
559	    /**
560	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
561	     * store, so a list/page of owners is counted without a per-owner query.
562	     *
563	     * @see #populateHouseholdSize(Owner)
564	     */
565	    private void populateHouseholdSizes(Collection<Owner> owners) {
566	        if (owners.isEmpty()) {
567	            return;
568	        }
569	        Map<String, Integer> sizes = new HashMap<>();
570	        for (Owner existing : ownerRepository.findAll()) {
571	            String householdId = existing.getHouseholdId();
572	            if (householdId != null && !householdId.isBlank()) {
573	                sizes.merge(householdId, 1, Integer::sum);
574	            }
575	        }
576	        for (Owner owner : owners) {
577	            String householdId = owner.getHouseholdId();
578	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
579	        }
580	    }
581	
582	    /**
583	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
584	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
585	     * joining {@code owner}'s normalized lastName and address.
586	     */
587	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
588	        for (Owner existing : household) {
589	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
590	                return existing.getHouseholdId();
591	            }
592	        }
593	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
594	            normalizeHouseholdAddress(owner.getAddress()));
595	    }
596	
597	    /**
598	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
599	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
600	     * household deterministically share the same identifier.
601	     */
602	    private static String generateHouseholdId(String lastName, String address) {
603	        try {
604	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
605	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
606	            StringBuilder sb = new StringBuilder();
607	            for (int i = 0; i < 6; i++) {
608	                sb.append(String.format("%02X", hash[i]));
609	            }
610	            return "HH-" + sb;
611	        } catch (NoSuchAlgorithmException e) {
612	            throw new IllegalStateException("SHA-256 not available", e);
613	        }
614	    }
615	
616	    /**
617	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
618	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
619	     */
620	    private static String normalizeHouseholdValue(String value) {
621	        if (value == null) {
622	            return "";
623	        }
624	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
625	    }
626	
627	    /**
628	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
629	     * form (never {@code null}), so duplicate detection and the shared household id compare
630	     * addresses using the same normalized representation that is stored and returned.
631	     */
632	    private static String normalizeHouseholdAddress(String address) {
633	        String normalized = normalizeAddress(address);
634	        return normalized == null ? "" : normalized;
635	    }
636	
637	    @Override
638	    @Transactional(readOnly = true)
639	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
640	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
641	        populateHouseholdSizes(owners);
642	        return owners;
643	    }
644	
645	    @Override
646	    @Transactional(readOnly = true)
647	    public Collection<Visit> findVisitsByPetId(int petId) {
648	        return visitRepository.findByPetId(petId);
649	    }
650	
651	    @Override
652	    @Transactional(readOnly = true)
653	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
654	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
655	    }
